/**
 * Every statement that mentions one resource: as subject, then as predicate, as object and as graph, each statement
 * once. A page streams these scans in the store's own index order, which stays the same while nothing is written, and
 * stops reading as soon as it has its rows and one more; it never reads the statements after the page. When the scans
 * ended within the page, the page knows the total; otherwise it says {@code has-more} and the total is asked for
 * separately with {@code counts=true}. Every operation is limited to five minutes.
 */
public class ExploreServlet extends TupleServlet {

	private final Logger logger = LoggerFactory.getLogger(ExploreServlet.class);

	protected static final String LIMIT = "limit_explore";

	protected static final int LIMIT_DEFAULT = 100;

	/** Metadata of a page whose total is not known yet: there is at least one row after it. */
	static final String HAS_MORE = "has-more";

	static final String TOTAL_RESULT_COUNT = "total-result-count";

	private final BrowseList browseList = new BrowseList(() -> repository);

	/** Pages run apart from the counts, so that long counts never hold a page back. */
	private final BrowseList pages = BrowseList.forPageOperations(() -> repository);

	private final long budgetMillis;

	public ExploreServlet() {
		this(BrowseList.BROWSE_BUDGET_MILLIS);
	}

	/** An Explore page that gives its operations the given time instead (tests use a shorter budget). */
	ExploreServlet(long budgetMillis) {
		super("subject", "predicate", "object", "context");
		this.budgetMillis = budgetMillis;
	}

	@Override
	public String[] getCookieNames() {
		return new String[] { LIMIT, "total_result_count", "show-datatypes" };
	}

	@Override
	public void service(final WorkbenchRequest req, final HttpServletResponse resp)
			throws Exception {
		try {
			super.service(req, resp);
		} catch (BadRequestException exc) {
			logger.warn(exc.toString(), exc);
			final TupleResultBuilder builder = getTupleResultBuilder(req, resp, resp.getOutputStream());
			builder.start("error-message");
			builder.link(List.of(INFO));
			builder.result(exc.getMessage());
			builder.end();
		}
	}

	@Override
	protected void service(final WorkbenchRequest req, final HttpServletResponse resp, final TupleResultBuilder builder,
			final RepositoryConnection con) throws Exception {
		final Value value = req.getValue("resource");
		logger.debug("resource = {}", value);
		if (BrowseList.countsRequested(req)) {
			total(builder, value);
			return;
		}

		// At worst, malicious parameter value could cause inaccurate
		// reporting of count in page.
		int knownTotal = req.getInt("know_total");
		final int offset = req.getInt("offset");
		int limit = LIMIT_DEFAULT;
		if (req.isParameterPresent(LIMIT)) {
			limit = req.getInt(LIMIT);
			if (0 == limit) {
				limit = Integer.MAX_VALUE;
			}
		}
		Page page = page(value, offset, limit, builder.showsRepositoryOrigins());
		long total = knownTotal > 0 ? knownTotal : page.complete() ? page.cursor().getTotalResultCount() : -1;
		// An unknown total also replaces the count another resource left in the cookie.
		this.cookies.addTotalResultCountCookie(req, resp, (int) Math.min(Integer.MAX_VALUE, Math.max(0, total)));
		if (total >= 0) {
			builder.metadata(TOTAL_RESULT_COUNT, total);
		} else {
			builder.metadata(HAS_MORE, true);
		}
		if (value != null) {
			// The resolved resource, so the page can group rows by the role it plays even for a prefixed name.
			builder.metadata("explore-resource", WorkbenchValueEncoder.encode(value));
		}
		if (page.origins() != null) {
			builder.repositoryOrigins(page.origins());
		}
		for (Statement statement : page.cursor().rows()) {
			builder.result(statement.getSubject(), statement.getPredicate(), statement.getObject(),
					statement.getContext());
		}
	}

	/** The rows of a page, read on their own connection, and the value factory that proves their blank nodes. */
	private record Page(ResultCursor cursor, ValueFactory origins) {

		/** Whether every scan ended within the page, so that the cursor counted every statement. */
		boolean complete() {
			return !cursor.hasMore();
		}
	}

	private Page page(Value value, int offset, int limit, boolean origins) throws Exception {
		Optional<Page> page = pages.withinBudget(() -> {
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.setParserConfig(NON_VERIFYING_PARSER_CONFIG);
				if (origins) {
					TupleResultBuilder.enableRepositoryOrigins(connection);
				}
				ResultCursor cursor = new ResultCursor(offset, limit, true);
				processResource(connection, value, cursor);
				return new Page(cursor, origins ? connection.getValueFactory() : null);
			}
		}, budgetMillis);
		return page.orElseThrow(() -> new OperationTimedOutException(BrowseList.timedOutMessage("Exploring")));
	}

	/**
	 * Answers the number of statements the pages show in all, or {@code counts-timed-out} when counting takes longer
	 * than the budget. An LMDB repository counts with one query; any other repository streams the statements and counts
	 * them, which is exact for federations and SPARQL endpoint proxies too.
	 */
	private void total(TupleResultBuilder builder, Value value) throws Exception {
		boolean lmdb = LmdbRepositories.isLmdbBacked(repository, manager, info == null ? null : info.getId());
		Optional<Long> total = browseList.sharedWithinBudget(
				List.of("explore", value == null ? "" : WorkbenchValueEncoder.encode(value), lmdb), () -> {
					try (RepositoryConnection connection = repository.getConnection()) {
						connection.setParserConfig(NON_VERIFYING_PARSER_CONFIG);
						if (lmdb && value != null) {
							return countQuery(connection, value);
						}
						ResultCursor cursor = new ResultCursor(0, Integer.MAX_VALUE, false);
						processResource(connection, value, cursor);
						return (long) cursor.getTotalResultCount();
					}
				}, budgetMillis);
		if (total.isEmpty()) {
			BrowseList.countsTimedOut(builder);
		} else {
			builder.metadata(TOTAL_RESULT_COUNT, total.get());
		}
	}

	private long countQuery(RepositoryConnection connection, Value value) {
		TupleQuery query = connection.prepareTupleQuery(countQuery(value));
		query.setBinding("resource", value);
		query.setMaxExecutionTime(BrowseList.BROWSE_BUDGET_SECONDS);
		long total = 0;
		try (TupleQueryResult result = query.evaluate()) {
			while (result.hasNext()) {
				Value count = result.next().getValue("total");
				total = count instanceof Literal literal ? literal.longValue() : 0;
			}
		}
		return total;
	}

	/**
	 * The count of the statements {@link #processResource} shows for {@code value}, bound as {@code ?resource}: the
	 * same four scans, each without the statements an earlier scan showed.
	 */
	static String countQuery(Value value) {
		List<String> scans = new ArrayList<>();
		if (value instanceof Resource) {
			scans.add("{ ?resource ?p ?o }");
		}
		if (value instanceof IRI) {
			scans.add("{ ?s ?resource ?o FILTER (!sameTerm(?s, ?resource)) }");
		}
		scans.add("{ ?s ?p ?resource FILTER (!sameTerm(?s, ?resource) && !sameTerm(?p, ?resource)) }");
		if (value instanceof Resource && !RDF4J.NIL.equals(value) && !SESAME.NIL.equals(value)) {
			// A query reads rdf4j:nil as the default graph, which the context scan does not mean.
			scans.add("{ GRAPH ?resource { ?s ?p ?o } "
					+ "FILTER (!sameTerm(?s, ?resource) && !sameTerm(?p, ?resource) && !sameTerm(?o, ?resource)) }");
		}
		return "SELECT (COUNT(*) AS ?total) WHERE { " + String.join(" UNION ", scans) + " }";
	}

	/**
	 * Streams the statements that mention {@code value} into {@code cursor}, as subject, predicate, object and graph in
	 * that order, each statement once. A rendering cursor stops the scans once its page is full and it has seen one
	 * more statement.
	 *
	 * @param con    the connection to the repository
	 * @param value  the value to query the repository for
	 * @param cursor where the statements go, relative to offset and limit
	 * @throws RDF4JException if there is an issue iterating through results
	 */
	protected void processResource(final RepositoryConnection con, final Value value, final ResultCursor cursor)
			throws RDF4JException {
		boolean resource = value instanceof Resource;
		if (resource) {
			export(con, cursor, (Resource) value, null, null);
			logger.debug("After subject, total = {}", cursor.getTotalResultCount());
		}
		if (value instanceof IRI) {
			export(con, cursor, null, (IRI) value, null);
			logger.debug("After predicate, total = {}", cursor.getTotalResultCount());
		}
		if (value != null) {
			export(con, cursor, null, null, value);
			logger.debug("After object, total = {}", cursor.getTotalResultCount());
		}
		if (resource) {
			export(con, cursor, null, null, null, (Resource) value);
			logger.debug("After context, total = {}", cursor.getTotalResultCount());
		}
	}

	/** Ends a scan once the page has its rows and one more. */
	private static final class PageFull extends RDFHandlerException {

		private static final long serialVersionUID = 1L;

		private PageFull() {
			super("The page is full");
		}
	}

	/**
	 * <p>
	 * Streams statements in the repository matching the given pattern into the cursor. It is an implicit assumption
	 * when this calls {@link #isFirstTimeSeen} that {@link #processResource} 's calls into here have been made in the
	 * following order:
	 * </p>
	 * <ol>
	 * <li>export(*, subject, null, null, null)</li>
	 * <li>export(*, null, predicate, null, null)</li>
	 * <li>export(*, null, null, object, null)</li>
	 * <li>export(*, null, null, null, context)</li>
	 * </ol>
	 *
	 * @param con     the connection to the repository
	 * @param cursor  used for keeping track of our location in the result set
	 * @param subj    the triple subject
	 * @param pred    the triple predicate
	 * @param obj     the triple object
	 * @param context the triple context
	 */
	private void export(RepositoryConnection con, ResultCursor cursor, Resource subj, IRI pred, Value obj,
			Resource... context) throws RDF4JException {
		if (cursor.hasMore()) {
			return;
		}
		try {
			con.exportStatements(subj, pred, obj, true, new AbstractRDFHandler() {
				@Override
				public void handleStatement(Statement statement) throws RDFHandlerException {
					if (Thread.currentThread().isInterrupted()) {
						throw new RDFHandlerException("Exploring was abandoned");
					}
					if (isFirstTimeSeen(statement, pred, obj, context)) {
						if (cursor.pageFull()) {
							cursor.more = true;
							throw new PageFull();
						}
						cursor.advance(statement);
					}
				}
			}, context);
		} catch (PageFull full) {
			// The scan stopped on purpose; a remote repository closes its response unread.
		}
	}

	/**
	 * Gets whether this is the first time the result quad has been seen.
	 *
	 * @param patternPredicate the predicate asked for, or null if another quad element was asked for
	 * @param patternObject    the object asked for, or null if another quad element was asked for
	 * @param result           the result statement to determine if we've already seen
	 * @param patternContext   the context asked for, or null if another quad element was asked for
	 * @return true, if this is the first time the quad has been seen, false otherwise
	 */
	private boolean isFirstTimeSeen(Statement result, IRI patternPredicate, Value patternObject,
			Resource... patternContext) {
		Resource resultSubject = (Resource) WorkbenchValueEncoder.canonicalValue(result.getSubject());
		IRI resultPredicate = result.getPredicate();
		Value resultObject = WorkbenchValueEncoder.canonicalValue(result.getObject());
		boolean firstTimeSeen;
		if (1 == patternContext.length) {
			// I.e., when context matches explore value.
			Resource ctx = patternContext[0];
			firstTimeSeen = !(ctx.equals(resultSubject) || ctx.equals(resultPredicate) || ctx.equals(resultObject));
		} else if (null != patternObject) {
			// I.e., when object matches explore value.
			firstTimeSeen = !(resultObject.equals(resultSubject) || resultObject.equals(resultPredicate));
		} else if (null != patternPredicate) {
			// I.e., when predicate matches explore value.
			firstTimeSeen = !(resultPredicate.equals(resultSubject));
		} else {
			// I.e., when subject matches explore value.
			firstTimeSeen = true;
		}
		return firstTimeSeen;
	}

	@Override
	public void destroy() {
		browseList.shutdown();
		pages.shutdown();
		super.destroy();
	}

	/**
	 * Class for keeping track of location within the result set, relative to offset and limit.
	 *
	 * @author Dale Visser
	 */
	protected class ResultCursor {

		private int untilFirst;

		private int totalResults = 0;

		private int renderedResults = 0;

		private final int limit;

		private final boolean render;

		private final List<Statement> rows = new ArrayList<>();

		private boolean more;

		/**
		 * @param offset the desired offset at which rendering should start
		 * @param limit  the desired maximum number of results to render
		 * @param render if false, suppresses any rendering and never stops the scans
		 */
		public ResultCursor(final int offset, final int limit, final boolean render) {
			this.render = render;
			this.limit = limit > 0 ? limit : Integer.MAX_VALUE;
			this.untilFirst = offset >= 0 ? offset : 0;
		}

		/**
		 * Gets the number of results seen. When {@link #hasMore()} is false, this is the number of all results.
		 *
		 * @return the number of times advance() has been called
		 */
		public int getTotalResultCount() {
			return this.totalResults;
		}

		/**
		 * Gets the number of results that were actually rendered.
		 *
		 * @return the number of times advance() has been called when this.mayRender() evaluated to true
		 */
		public int getRenderedResultCount() {
			return this.renderedResults;
		}

		/** The rendered statements, in the order they were seen. */
		public List<Statement> rows() {
			return rows;
		}

		/** Whether the scans stopped because a statement came after the full page. */
		public boolean hasMore() {
			return more;
		}

		/**
		 * @return whether it is allowed to render the next result
		 */
		public boolean mayRender() {
			return this.render && (this.untilFirst == 0 && this.renderedResults < this.limit);
		}

		/** Whether a rendering cursor has rendered its whole page. */
		boolean pageFull() {
			return this.render && this.untilFirst == 0 && this.renderedResults >= this.limit;
		}

		/**
		 * Advances the cursor past one result, keeping it when it is on the page.
		 */
		public void advance(Statement statement) {
			this.totalResults++;
			if (this.mayRender()) {
				this.rows.add(statement);
				this.renderedResults++;
			}

			if (this.untilFirst > 0) {
				this.untilFirst--;
			}
		}
	}
}
